begin;
create table lista_espera(
 id bigint generated by default as identity primary key,paciente_id bigint not null references perfiles_pacientes(id),medico_id bigint not null references perfiles_medicos(id),cita_id bigint references citas(id),
 desde date not null,hasta date not null,inicio time not null,fin time not null,estado text not null default 'activa' check(estado in('activa','resuelta','retirada')),
 autor bigint not null references usuarios(id),creado_en timestamptz not null default clock_timestamp(),revision bigint not null default 1,check(hasta>=desde and hasta-desde<=56 and fin>inicio)
);
create index lista_espera_cola on lista_espera(medico_id,creado_en,id) where estado='activa';
create unique index lista_espera_activa on lista_espera(paciente_id,medico_id) where estado='activa';
create table espera_ofertas(
 id uuid primary key default gen_random_uuid(),entrada_id bigint not null references lista_espera(id),medico_id bigint not null references perfiles_medicos(id),inicio timestamptz not null,fin timestamptz not null,
 vence_en timestamptz not null,estado text not null default 'pendiente' check(estado in('pendiente','aceptada','rechazada','vencida','revocada')),cita_version text,cita_resultado bigint references citas(id),telegram_vinculado_en timestamptz,creado_en timestamptz not null default clock_timestamp(),check(fin>inicio)
);
create index espera_vencimiento on espera_ofertas(vence_en) where estado='pendiente';
create unique index espera_una_oferta on espera_ofertas(entrada_id) where estado='pendiente';
alter table espera_ofertas add constraint espera_oferta_turno_unico exclude using gist(medico_id with =,tstzrange(inicio,fin,'[)') with &&) where(estado='pendiente');
create table controles_seguimiento(
 id bigint generated by default as identity primary key,paciente_id bigint not null references perfiles_pacientes(id),medico_id bigint not null references perfiles_medicos(id),cita_origen bigint references citas(id),
 fecha date not null,titulo text not null check(length(trim(titulo)) between 1 and 120),indicaciones text not null default '' check(length(indicaciones)<=1000),dias_aviso integer not null default 1 check(dias_aviso between 0 and 30),
 estado text not null default 'pendiente' check(estado in('pendiente','cita_agendada','completado','cancelado')),cita_agendada bigint references citas(id),nota_cierre text,revision bigint not null default 1,creado_en timestamptz not null default clock_timestamp()
);
create index controles_pendientes on controles_seguimiento(fecha) where estado='pendiente';
alter table lista_espera enable row level security;alter table espera_ofertas enable row level security;alter table controles_seguimiento enable row level security;
revoke all on lista_espera,espera_ofertas,controles_seguimiento from public,anon,authenticated;
grant all on lista_espera,espera_ofertas,controles_seguimiento to service_role;
grant usage,select on sequence lista_espera_id_seq,controles_seguimiento_id_seq to service_role;
alter table notificaciones add column espera_oferta_id uuid references espera_ofertas(id) on delete set null,add column seguimiento_id bigint references controles_seguimiento(id) on delete set null;

create function public.clinica_espera_opciones(p_entrada bigint,p_desde date default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare l lista_espera;c citas;u bigint;r jsonb;
begin
 select * into l from lista_espera where id=p_entrada and estado='activa';
 if l.id is null then raise exception 'La solicitud de espera ya no está activa';end if;
 select usuario_id into u from perfiles_pacientes where id=l.paciente_id and esta_activo;
 if l.cita_id is null then r:=clinica_turnos_reserva(l.paciente_id,l.medico_id,p_desde);
 else
  select * into c from citas where id=l.cita_id and paciente_id=l.paciente_id and medico_id=l.medico_id;
  if c.id is null then raise exception 'La cita de referencia cambió';end if;
  r:=clinica_turnos_cita_actor(u,c.id,clinica_version_reserva(c),p_desde);
 end if;
 return r||jsonb_build_object('turnos',coalesce((select jsonb_agg(x order by x->>'inicio') from jsonb_array_elements(r->'turnos') x where
  (x->>'inicio')::timestamptz<coalesce(c.inicio,'infinity'::timestamptz) and ((x->>'inicio')::timestamptz at time zone 'America/Mexico_City')::date between l.desde and l.hasta
  and ((x->>'inicio')::timestamptz at time zone 'America/Mexico_City')::time>=l.inicio and ((x->>'fin')::timestamptz at time zone 'America/Mexico_City')::time<=l.fin),'[]'::jsonb));
end $$;

create function public.clinica_espera_ofrecer(p_entrada bigint,p_inicio timestamptz) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare l lista_espera;u usuarios;c citas;opciones jsonb;elegido jsonb;o espera_ofertas;m text;
begin
 perform pg_advisory_xact_lock(37201,0);
 update espera_ofertas set estado='vencida' where estado='pendiente' and vence_en<=clock_timestamp();
 select * into l from lista_espera where id=p_entrada and estado='activa' for update;
 select uu.* into u from usuarios uu join perfiles_pacientes p on p.usuario_id=uu.id and p.esta_activo where p.id=l.paciente_id and uu.esta_activo and uu.rol='paciente';
 if l.id is null or u.id is null or u.auth_user_id is null then raise exception 'El paciente necesita una cuenta activa para aceptar ofertas';end if;
 opciones:=clinica_espera_opciones(l.id,(p_inicio at time zone 'America/Mexico_City')::date);
 select x into elegido from jsonb_array_elements(opciones->'turnos') x where (x->>'inicio')::timestamptz=p_inicio;
 if elegido is null then raise exception 'El turno no está disponible o no coincide con las preferencias de espera' using errcode='23P01';end if;
 if exists(select 1 from espera_ofertas where entrada_id=l.id and estado='pendiente') then raise exception 'Este paciente ya tiene una oferta pendiente';end if;
 if l.cita_id is not null then select * into c from citas where id=l.cita_id;end if;
 insert into espera_ofertas(entrada_id,medico_id,inicio,fin,vence_en,cita_version,telegram_vinculado_en) values(l.id,l.medico_id,p_inicio,(elegido->>'fin')::timestamptz,least(clock_timestamp()+interval '20 minutes',p_inicio),case when c.id is not null then clinica_version_reserva(c) end,(select vinculado_en from telegram_cuentas where usuario_id=u.id and activo)) returning * into o;
 select um.nombre_completo into m from perfiles_medicos pm join usuarios um on um.id=pm.usuario_id where pm.id=l.medico_id;
 insert into notificaciones(usuario_id,tipo,titulo,mensaje,clave,espera_oferta_id) values(u.id,'espera_oferta','Hay un horario disponible',format('Se liberó un horario con %s para el %s a las %s (Ciudad de México). Tienes hasta las %s para responder desde Lista de espera. La cita se reserva solo cuando aceptas; el turno aún puede ocuparse.',m,to_char(o.inicio at time zone 'America/Mexico_City','DD/MM/YYYY'),to_char(o.inicio at time zone 'America/Mexico_City','HH24:MI'),to_char(o.vence_en at time zone 'America/Mexico_City','HH24:MI')),'oferta:'||o.id,o.id);
 return jsonb_build_object('ok',true,'id',o.id,'mensaje','Oferta enviada. La reserva cambiará solo si el paciente acepta y el horario sigue libre.');
end $$;

-- Cada hueco se propone por orden de inscripción, una vez por paciente y horario.
create function public.clinica_espera_siguiente(p_medico bigint,p_inicio timestamptz,p_excluir bigint default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare l lista_espera;
begin
 perform pg_advisory_xact_lock(37201,0);
 if p_inicio<=clock_timestamp() or exists(select 1 from espera_ofertas where medico_id=p_medico and inicio=p_inicio and estado='pendiente' and vence_en>clock_timestamp()) then return;end if;
 for l in select ll.* from lista_espera ll join perfiles_pacientes p on p.id=ll.paciente_id and p.esta_activo join usuarios u on u.id=p.usuario_id and u.esta_activo and u.auth_user_id is not null
 where ll.estado='activa' and ll.medico_id=p_medico and ll.paciente_id is distinct from p_excluir and (p_inicio at time zone 'America/Mexico_City')::date between ll.desde and ll.hasta
 and not exists(select 1 from espera_ofertas where entrada_id=ll.id and (inicio=p_inicio or estado='pendiente' and vence_en>clock_timestamp())) order by ll.creado_en,ll.id limit 100 loop
  begin perform clinica_espera_ofrecer(l.id,p_inicio);return;exception when sqlstate '23P01' or sqlstate '23505' or sqlstate 'P0001' or sqlstate '40001' then null;end;
 end loop;
end $$;
revoke all on function clinica_espera_siguiente(bigint,timestamptz,bigint) from public,anon,authenticated,service_role;

create function public.clinica_espera_responder_actor(p_usuario bigint,p_oferta uuid,p_accion text,p_canal text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare o espera_ofertas;l lista_espera;u usuarios;c citas;r jsonb;
begin
 perform pg_advisory_xact_lock(37201,0);
 select * into u from usuarios where id=p_usuario and esta_activo and rol='paciente';
 select oo.* into o from espera_ofertas oo join lista_espera ll on ll.id=oo.entrada_id join perfiles_pacientes p on p.id=ll.paciente_id and p.usuario_id=u.id and p.esta_activo where oo.id=p_oferta for update of oo;
 if u.id is null or o.id is null then raise exception 'La oferta no pertenece a tu cuenta' using errcode='42501';end if;
 if p_accion not in('aceptar','rechazar') or p_canal not in('aplicacion','telegram') then raise exception 'Respuesta inválida';end if;
 if o.estado='aceptada' and p_accion='aceptar' then return jsonb_build_object('ok',true,'id',o.cita_resultado,'mensaje','Esta oferta ya fue aceptada.');end if;
 select * into l from lista_espera where id=o.entrada_id for update;
 if o.estado<>'pendiente' or o.vence_en<=clock_timestamp() or l.estado<>'activa' then raise exception 'La oferta venció o ya fue resuelta. Consulta la lista de espera' using errcode='40001';end if;
 if p_accion='rechazar' then update espera_ofertas set estado='rechazada' where id=o.id;perform clinica_espera_siguiente(o.medico_id,o.inicio,l.paciente_id);return jsonb_build_object('ok',true,'mensaje','Oferta rechazada. Conservas tu lugar en la lista de espera.');end if;
 if l.cita_id is not null then
  select * into c from citas where id=l.cita_id;
  if c.inicio<=clock_timestamp()+interval '2 hours' or c.inicio<=o.inicio then raise exception 'La cita actual ya no permite adelantarse. Conserva su horario o contacta con recepción';end if;
  r:=clinica_reagendar_turno_actor(u.id,c.id,o.cita_version,o.inicio,p_canal);o.cita_resultado:=c.id;
 else
  r:=clinica_agendar_paciente_actor(u.id,l.medico_id,o.inicio,o.fin,o.id,'Cita aceptada desde lista de espera');o.cita_resultado:=(r->>'id')::bigint;
 end if;
 update espera_ofertas set estado='aceptada',cita_resultado=o.cita_resultado where id=o.id;
 update lista_espera set estado='resuelta',revision=revision+1 where id=l.id;
 return r||jsonb_build_object('ok',true,'id',o.cita_resultado);
end $$;

create function public.clinica_espera_mutar(p_accion text,p_datos jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare rol text:=clinica_rol();u usuarios;l lista_espera;c citas;p bigint;n bigint;
begin
 select * into u from usuarios where auth_user_id=auth.uid() and esta_activo;
 if rol is null or rol not in('admin','recepcionista','paciente') then raise exception 'Sin acceso a lista de espera' using errcode='42501';end if;
 if p_accion in('aceptar','rechazar') then return clinica_espera_responder_actor(u.id,(p_datos->>'ofertaId')::uuid,p_accion,'aplicacion');end if;
 if p_accion='inscribir' then
  if rol='paciente' then select id into p from perfiles_pacientes where usuario_id=u.id and esta_activo;else p:=(p_datos->>'pacienteId')::bigint;end if;
  if not exists(select 1 from perfiles_pacientes pp join usuarios uu on uu.id=pp.usuario_id and uu.esta_activo and uu.rol='paciente' where pp.id=p and pp.esta_activo) then raise exception 'Paciente no disponible';end if;
  if not exists(select 1 from perfiles_medicos m join usuarios um on um.id=m.usuario_id and um.esta_activo where m.id=(p_datos->>'medicoId')::bigint and m.esta_activo) then raise exception 'Selecciona un médico activo';end if;
  if nullif(p_datos->>'citaId','') is not null then
   select * into c from citas where id=(p_datos->>'citaId')::bigint and paciente_id=p and medico_id=(p_datos->>'medicoId')::bigint and estado in('pendiente','confirmada') and inicio>clock_timestamp()+interval '2 hours';
   if c.id is null or exists(select 1 from recepcion_llegadas where cita_id=c.id and inicio_cita=c.inicio) then raise exception 'La cita debe estar sin llegada y a más de dos horas para solicitar adelanto';end if;
  end if;
  if (p_datos->>'desde')::date<(clock_timestamp() at time zone 'America/Mexico_City')::date or (p_datos->>'hasta')::date>(clock_timestamp() at time zone 'America/Mexico_City')::date+56 then raise exception 'Elige fechas dentro de los próximos 56 días';end if;
  insert into lista_espera(paciente_id,medico_id,cita_id,desde,hasta,inicio,fin,autor) values(p,(p_datos->>'medicoId')::bigint,c.id,(p_datos->>'desde')::date,(p_datos->>'hasta')::date,(p_datos->>'inicio')::time,(p_datos->>'fin')::time,u.id) returning id into n;
  return jsonb_build_object('ok',true,'id',n,'mensaje','Solicitud registrada. No se reservó ni cambió ninguna cita.');
 end if;
 select ll.* into l from lista_espera ll join perfiles_pacientes pp on pp.id=ll.paciente_id where ll.id=(p_datos->>'id')::bigint and (rol in('admin','recepcionista') or pp.usuario_id=u.id) for update of ll;
 if l.id is null then raise exception 'Solicitud sin acceso' using errcode='42501';end if;
 if md5(to_jsonb(l)::text) is distinct from p_datos->>'version' then raise exception 'La solicitud cambió. Actualiza la lista' using errcode='40001';end if;
 if p_accion='retirar' then update lista_espera set estado='retirada',revision=revision+1 where id=l.id;update espera_ofertas set estado='revocada' where entrada_id=l.id and estado='pendiente';
 elsif p_accion='ofertar' and rol in('admin','recepcionista') then return clinica_espera_ofrecer(l.id,(p_datos->>'inicio')::timestamptz);
 else raise exception 'Acción de espera inválida';end if;
 return jsonb_build_object('ok',true,'mensaje','Solicitud retirada. Las citas existentes se conservan.');
end $$;

create function public.clinica_espera_panel(p_entrada bigint default null,p_desde date default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare u usuarios;ids bigint[];entrada lista_espera;
begin
 perform clinica_requerir_sesion();select * into u from usuarios where auth_user_id=auth.uid() and esta_activo;
 if u.rol is null or u.rol not in('admin','recepcionista','paciente') then raise exception 'Sin acceso a lista de espera' using errcode='42501';end if;
 select array_agg(p.id) into ids from perfiles_pacientes p join usuarios uu on uu.id=p.usuario_id and uu.esta_activo and uu.rol='paciente' where p.esta_activo and (u.rol in('admin','recepcionista') or uu.id=u.id);
 if p_entrada is not null then
  select * into entrada from lista_espera where id=p_entrada and paciente_id=any(ids);
  if entrada.id is null then raise exception 'Solicitud sin acceso' using errcode='42501';end if;
  return clinica_espera_opciones(entrada.id,p_desde);
 end if;
 return jsonb_build_object('pacientes',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'nombre',uu.nombre_completo,'cuenta',uu.auth_user_id is not null)) from perfiles_pacientes p join usuarios uu on uu.id=p.usuario_id where p.id=any(ids)),'[]'::jsonb),
 'medicos',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'nombre',uu.nombre_completo)) from perfiles_medicos m join usuarios uu on uu.id=m.usuario_id and uu.esta_activo where m.esta_activo),'[]'::jsonb),
 'citas',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'pacienteId',c.paciente_id,'medicoId',c.medico_id,'inicio',c.inicio)) from citas c where c.paciente_id=any(ids) and c.estado in('pendiente','confirmada') and c.inicio>clock_timestamp()+interval '2 hours'),'[]'::jsonb),
 'solicitudes',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'pacienteId',l.paciente_id,'paciente',uu.nombre_completo,'medicoId',l.medico_id,'medico',um.nombre_completo,'citaId',l.cita_id,'desde',l.desde,'hasta',l.hasta,'inicio',l.inicio,'fin',l.fin,'estado',l.estado,'version',md5(to_jsonb(l)::text),'creado',l.creado_en) order by l.creado_en) from lista_espera l join perfiles_pacientes p on p.id=l.paciente_id join usuarios uu on uu.id=p.usuario_id join perfiles_medicos m on m.id=l.medico_id join usuarios um on um.id=m.usuario_id where l.paciente_id=any(ids) and (l.estado='activa' or l.creado_en>clock_timestamp()-interval '30 days')),'[]'::jsonb),
 'ofertas',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'entradaId',o.entrada_id,'pacienteId',l.paciente_id,'inicio',o.inicio,'fin',o.fin,'vence',o.vence_en,'estado',case when o.estado='pendiente' and o.vence_en<=clock_timestamp() then 'vencida' else o.estado end) order by o.creado_en desc) from espera_ofertas o join lista_espera l on l.id=o.entrada_id where l.paciente_id=any(ids) and o.creado_en>clock_timestamp()-interval '7 days'),'[]'::jsonb));
end $$;

create function public.clinica_espera_cita_liberada() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare l lista_espera;r jsonb;
begin
 if old.estado not in('pendiente','confirmada') or (new.estado in('pendiente','confirmada') and (new.inicio,new.fin,new.medico_id) is not distinct from (old.inicio,old.fin,old.medico_id)) then return new;end if;
 if new.estado::text like 'cancelada%' or new.estado='no_asistio' then
  update lista_espera set estado='retirada',revision=revision+1 where cita_id=new.id and estado='activa';
 end if;
 update espera_ofertas o set estado='revocada' from lista_espera ll where ll.id=o.entrada_id and ll.cita_id=new.id and o.estado='pendiente';
 if old.inicio<=clock_timestamp() then return new;end if;
 perform clinica_espera_siguiente(old.medico_id,old.inicio,old.paciente_id);
 return new;
end $$;
create trigger espera_cita_liberada after update on citas for each row execute function clinica_espera_cita_liberada();

create function public.clinica_controles_mutar(p_accion text,p_datos jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare u usuarios;s controles_seguimiento;c citas;p bigint;m bigint;n bigint;
begin
 select * into u from usuarios where auth_user_id=auth.uid() and esta_activo;
 if u.rol not in('medico','paciente') or u.id is null then raise exception 'Los controles corresponden al médico tratante y su paciente' using errcode='42501';end if;
 if p_accion='crear' then
  if u.rol<>'medico' then raise exception 'Solo el médico programa controles' using errcode='42501';end if;
  m:=clinica_medico();p:=(p_datos->>'pacienteId')::bigint;
  if m is null or not clinica_paciente(p) then raise exception 'Paciente fuera de tu atención' using errcode='42501';end if;
  if nullif(p_datos->>'citaId','') is not null and not exists(select 1 from citas where id=(p_datos->>'citaId')::bigint and medico_id=m and paciente_id=p) then raise exception 'La consulta de referencia no pertenece a tu atención' using errcode='42501';end if;
  if (p_datos->>'fecha')::date<(clock_timestamp() at time zone 'America/Mexico_City')::date or (p_datos->>'fecha')::date>(clock_timestamp() at time zone 'America/Mexico_City')::date+366 then raise exception 'Elige una fecha de control entre hoy y el próximo año';end if;
  insert into controles_seguimiento(paciente_id,medico_id,cita_origen,fecha,titulo,indicaciones,dias_aviso) values(p,m,nullif(p_datos->>'citaId','')::bigint,(p_datos->>'fecha')::date,trim(p_datos->>'titulo'),trim(coalesce(p_datos->>'indicaciones','')),coalesce((p_datos->>'diasAviso')::integer,1)) returning * into s;
  insert into notificaciones(usuario_id,tipo,titulo,mensaje,clave,seguimiento_id) select usuario_id,'seguimiento','Tienes un control por programar','Tu médico indicó un control para el '||to_char(s.fecha,'DD/MM/YYYY')||'. Revisa Mis controles para consultar las indicaciones y buscar una cita. Aún no hay una reserva.','control:'||s.id||':creado',s.id from perfiles_pacientes where id=p;
  return jsonb_build_object('ok',true,'id',s.id,'mensaje','Control programado. El paciente recibirá un aviso; no se creó una cita.');
 end if;
 select ss.* into s from controles_seguimiento ss join perfiles_pacientes pp on pp.id=ss.paciente_id where ss.id=(p_datos->>'id')::bigint and (u.rol='medico' and ss.medico_id=clinica_medico() or u.rol='paciente' and pp.usuario_id=u.id) for update of ss;
 if s.id is null then raise exception 'Control fuera de tu atención' using errcode='42501';end if;
 if md5(to_jsonb(s)::text) is distinct from p_datos->>'version' then raise exception 'El control cambió. Actualiza la pantalla' using errcode='40001';end if;
 if s.estado not in('pendiente','cita_agendada') then raise exception 'El control ya fue cerrado';end if;
 if p_accion='vincular_cita' then
  if u.rol<>'paciente' then raise exception 'La vinculación corresponde al paciente' using errcode='42501';end if;
  select * into c from citas where id=(p_datos->>'citaId')::bigint and paciente_id=s.paciente_id and medico_id=s.medico_id and estado in('pendiente','confirmada') and inicio>clock_timestamp();
  if c.id is null then raise exception 'Selecciona una cita futura propia con el médico del control';end if;
  update controles_seguimiento set estado='cita_agendada',cita_agendada=c.id,revision=revision+1 where id=s.id;
 elsif p_accion in('completar','cancelar') and u.rol='medico' then
  if length(trim(coalesce(p_datos->>'nota',''))) not between 1 and 1000 then raise exception 'Registra el motivo o resultado del cierre';end if;
  update controles_seguimiento set estado=case when p_accion='completar' then 'completado' else 'cancelado' end,nota_cierre=trim(p_datos->>'nota'),revision=revision+1 where id=s.id;
 else raise exception 'Acción de seguimiento inválida';end if;
 return jsonb_build_object('ok',true,'mensaje','Control actualizado. Las citas existentes conservan su propia gestión.');
end $$;

create function public.clinica_controles_panel() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare u usuarios;ids bigint[];
begin
 perform clinica_requerir_sesion();select * into u from usuarios where auth_user_id=auth.uid() and esta_activo;
 if u.id is null or u.rol not in('medico','paciente') then raise exception 'Sin acceso a controles clínicos' using errcode='42501';end if;
 select array_agg(p.id) into ids from perfiles_pacientes p join usuarios uu on uu.id=p.usuario_id and uu.esta_activo where p.esta_activo and (u.rol='paciente' and p.usuario_id=u.id or u.rol='medico' and clinica_paciente(p.id));
 return jsonb_build_object('pacientes',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'nombre',uu.nombre_completo)) from perfiles_pacientes p join usuarios uu on uu.id=p.usuario_id where p.id=any(ids)),'[]'::jsonb),
 'controles',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'pacienteId',s.paciente_id,'paciente',up.nombre_completo,'medicoId',s.medico_id,'medico',um.nombre_completo,'fecha',s.fecha,'titulo',s.titulo,'indicaciones',s.indicaciones,'diasAviso',s.dias_aviso,'estado',s.estado,'citaId',s.cita_agendada,'nota',s.nota_cierre,'version',md5(to_jsonb(s)::text)) order by s.fecha,s.id) from controles_seguimiento s join perfiles_pacientes p on p.id=s.paciente_id join usuarios up on up.id=p.usuario_id join perfiles_medicos m on m.id=s.medico_id join usuarios um on um.id=m.usuario_id where s.paciente_id=any(ids) and (u.rol='paciente' or s.medico_id=clinica_medico()) and (s.estado in('pendiente','cita_agendada') or s.fecha>=(clock_timestamp() at time zone 'America/Mexico_City')::date-90)),'[]'::jsonb),
 'citas',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'pacienteId',c.paciente_id,'medicoId',c.medico_id,'inicio',c.inicio)) from citas c where c.paciente_id=any(ids) and (u.rol='paciente' or c.medico_id=clinica_medico()) and c.estado in('pendiente','confirmada') and c.inicio>clock_timestamp()),'[]'::jsonb));
end $$;
create function public.clinica_control_cita_estado() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if new.estado='atendida' then update controles_seguimiento set estado='completado',nota_cierre='Consulta de control finalizada por el médico.',revision=revision+1 where cita_agendada=new.id and estado='cita_agendada';
 elsif new.estado in('cancelada_paciente','cancelada_medico','no_asistio') then update controles_seguimiento set estado='pendiente',cita_agendada=null,revision=revision+1 where cita_agendada=new.id and estado='cita_agendada';end if;
 return new;
end $$;
create trigger control_cita_estado after update of estado on citas for each row execute function clinica_control_cita_estado();
create trigger lista_espera_auditar after insert or update on lista_espera for each row execute function clinica_auditar();
create trigger espera_ofertas_auditar after insert or update on espera_ofertas for each row execute function clinica_auditar();
create trigger controles_auditar after insert or update on controles_seguimiento for each row execute function clinica_auditar();
revoke all on function clinica_espera_opciones(bigint,date),clinica_espera_ofrecer(bigint,timestamptz),clinica_espera_responder_actor(bigint,uuid,text,text),clinica_espera_mutar(text,jsonb),clinica_espera_cita_liberada(),clinica_controles_mutar(text,jsonb),clinica_control_cita_estado() from public,anon,authenticated,service_role;
revoke all on function clinica_espera_panel(bigint,date),clinica_controles_panel() from public,anon;
grant execute on function clinica_espera_panel(bigint,date),clinica_controles_panel() to authenticated;
create or replace function public.clinica_version() returns integer language sql stable as $$select 36$$;
notify pgrst,'reload schema';commit;
